// src/effects/club-fx.ts
var smokes = [];
var fxWasOn = true;
var DEFAULTS = {
  beatFlash: true,
  smokeStrength: 1,
  smokeAngleDeg: 0,
  lightHeight: 7
};
var installed = false;
var opts = DEFAULTS;
var rigs = [];
var elapsed = 0;
var reaction = null;
var blackoutMode = false;
var SPOT_COLORS = [
  Color32.create(1, 0.2, 0.75),
  Color32.create(0.2, 0.85, 1),
  Color32.create(1, 0.72, 0.25),
  Color32.create(0.35, 1, 0.55)
];
var BEAT_S = 60 / 124;
function beat() {
  if (!opts.beatFlash || !isMusicPlaying())
    return 0;
  const phase2 = elapsed % BEAT_S / BEAT_S;
  return Math.max(0, Math.pow(1 - phase2 * 2.2, 3));
}
function spawnSpotlight(center, color, rig2, lampY) {
  const e = engine.addEntity();
  Transform2.create(e, {
    position: Vector33.create(center.x, lampY, center.z),
    rotation: Quaternion2.fromEulerDegrees(rig2.tilt, rig2.baseYaw, 0)
  });
  LightSource3.create(e, {
    active: true,
    color,
    intensity: rig2.baseIntensity,
    range: Math.max(18, lampY - center.y + 12),
    shadow: false,
    type: LightSource3.Type.Spot({ innerAngle: 10, outerAngle: 26 })
  });
  const beamLen = Math.max(7, lampY - center.y + 1);
  const beamWide = 2.6;
  const beam = engine.addEntity();
  Transform2.create(beam, {
    parent: e,
    position: Vector33.create(0, 0, beamLen / 2),
    rotation: Quaternion2.fromEulerDegrees(90, 0, 0),
    scale: Vector33.create(1, beamLen, 1)
  });
  MeshRenderer3.setCylinder(beam, 0.05, beamWide);
  Material3.setPbrMaterial(beam, {
    albedoColor: Color42.create(color.r, color.g, color.b, 0.1),
    emissiveColor: color,
    emissiveIntensity: 1.5,
    metallic: 0,
    roughness: 1,
    castShadows: false
  });
  rigs.push({ entity: e, beam, color, ...rig2 });
}
function setFxActive(on) {
  for (const r of rigs) {
    const light = LightSource3.getMutableOrNull(r.entity);
    if (light)
      light.active = on;
    Material3.setPbrMaterial(r.beam, {
      albedoColor: Color42.create(r.color.r, r.color.g, r.color.b, on ? 0.1 : 0),
      emissiveColor: r.color,
      emissiveIntensity: on ? 1.3 : 0,
      metallic: 0,
      roughness: 1,
      castShadows: false
    });
  }
  for (const s of smokes) {
    const ps = ParticleSystem3.getMutableOrNull(s);
    if (ps)
      ps.active = on;
  }
}
function sweepSystem(dt) {
  const on = isClubAtmosphereActive();
  if (on !== fxWasOn) {
    fxWasOn = on;
    setFxActive(on);
  }
  if (!on)
    return;
  elapsed += dt;
  const b3 = beat();
  const now = Date.now();
  if (reaction && now > reaction.startedAt + reaction.durationMs)
    reaction = null;
  const activeReaction = reaction && now >= reaction.startedAt ? reaction : null;
  for (let index2 = 0; index2 < rigs.length; index2++) {
    const r = rigs[index2];
    const yaw = r.baseYaw + Math.sin(elapsed * r.speed + r.phase) * r.sweep;
    const t2 = Transform2.getMutable(r.entity);
    t2.rotation = Quaternion2.fromEulerDegrees(r.tilt, yaw, 0);
    const light = LightSource3.getMutableOrNull(r.entity);
    let multiplier = 1 + b3 * 1.6;
    let color = r.color;
    if (blackoutMode) {
      const pulse2 = 0.7 + Math.abs(Math.sin(elapsed * 2.4)) * 0.3;
      multiplier = index2 === 0 ? 4.2 * pulse2 : 0.08;
      color = index2 === 0 ? Color32.White() : Color32.create(0.05, 0.05, 0.08);
    } else if (activeReaction) {
      const pulse2 = 0.55 + Math.abs(Math.sin(elapsed * (3 + activeReaction.intensity)));
      if (activeReaction.mood === "positive" && activeReaction.intensity >= 4) {
        multiplier = index2 === 0 ? 3.8 * pulse2 : 0.12;
        color = index2 === 0 ? Color32.White() : r.color;
      } else if (activeReaction.mood === "negative") {
        multiplier = activeReaction.intensity >= 3 ? 0.18 : 0.45;
        color = Color32.create(0.3, 0.35, 0.55);
      } else if (activeReaction.mood === "aggressive") {
        multiplier = (1.3 + activeReaction.intensity * 0.45) * pulse2;
        color = Color32.create(1, 0.08, 0.05);
      } else {
        multiplier += activeReaction.intensity * 0.55 * pulse2;
      }
    }
    if (light) {
      light.intensity = r.baseIntensity * multiplier;
      light.color = color;
    }
    Material3.setPbrMaterial(r.beam, {
      albedoColor: Color42.create(color.r, color.g, color.b, 0.08 + b3 * 0.14),
      emissiveColor: color,
      emissiveIntensity: 1.3 + b3 * 2.2 + (activeReaction ? activeReaction.intensity * 0.55 : 0),
      metallic: 0,
      roughness: 1,
      castShadows: false
    });
  }
}
function setClubFxReaction(cue2) {
  reaction = cue2;
}
function setClubFxBlackout(active3) {
  blackoutMode = active3;
}
function spawnSmokeOutlet(pos, angleRad) {
  const strength = Math.max(0.1, opts.smokeStrength);
  const push = Vector33.create(
    Math.sin(angleRad) * 1.6 * strength,
    2.4 * strength,
    Math.cos(angleRad) * 1.6 * strength
  );
  const emitter = engine.addEntity();
  smokes.push(emitter);
  Transform2.create(emitter, { position: Vector33.create(pos.x, pos.y + 0.05, pos.z) });
  ParticleSystem3.create(emitter, {
    active: true,
    rate: 26 * strength,
    // continuous haze, not a shy puff
    maxParticles: 600,
    lifetime: 5.5,
    gravity: -0.02,
    additionalForce: push,
    initialSize: { start: 0.4, end: 0.4 },
    sizeOverTime: { start: 0.8, end: 4.5 },
    initialVelocitySpeed: { start: 2.2 * strength, end: 3.4 * strength },
    initialColor: {
      start: Color42.create(0.85, 0.85, 0.9, 0.6),
      end: Color42.create(0.85, 0.85, 0.9, 0.6)
    },
    colorOverTime: {
      start: Color42.create(0.85, 0.85, 0.9, 0.55),
      end: Color42.create(0.72, 0.72, 0.8, 0)
    },
    billboard: true,
    loop: true,
    simulationSpace: 1,
    // PSS_WORLD — drifts across the floor
    shape: ParticleSystem3.Shape.Cone({ angle: 20, radius: 0.25 })
  });
}
function initClubFx(center, zoneRadius2, options) {
  if (installed)
    return;
  installed = true;
  opts = { ...DEFAULTS, ...options };
  const lampY = center.y + Math.max(3, opts.lightHeight);
  const tilt = 66;
  const sweep = 40;
  for (let i = 0; i < 4; i++) {
    spawnSpotlight(
      center,
      SPOT_COLORS[i],
      {
        baseYaw: i * 90,
        tilt,
        sweep,
        speed: 0.7 + i * 0.12,
        phase: i * 1.7,
        baseIntensity: 24e3
      },
      lampY
    );
  }
  engine.addSystem(sweepSystem);
  const ang = opts.smokeAngleDeg * Math.PI / 180;
  const edge = Math.max(0.8, zoneRadius2 - 0.5);
  spawnSmokeOutlet({ x: center.x - edge * 0.5, y: center.y, z: center.z - edge * 0.7 }, ang);
  spawnSmokeOutlet({ x: center.x + edge * 0.5, y: center.y, z: center.z - edge * 0.7 }, ang);
  console.log("[club-fx] lights + ground smoke installed");
}

