// shared/punch-arena-spotlight.ts
var SLOT_MS = 8e3;
var CARD_MS = 6e3;
var INTRO_MS = 1200;
function punchArenaSpotlight(tonight, saved, lastHit, now) {
  const valid = (score) => Number.isSafeInteger(score) && score > 0;
  const cards = tonight.slice(0, 3).flatMap((entry, index2) => valid(entry.score) ? [{ label: `TONIGHT #${index2 + 1} \xB7 ${entry.name.slice(0, 16).toUpperCase()}`, score: entry.score, icon: index2 === 0 ? "crown" : "star" }] : []);
  if (saved[0] && valid(saved[0].score)) {
    cards.push({ label: `ALL-TIME RECORD \xB7 ${saved[0].name.slice(0, 16).toUpperCase()}`, score: saved[0].score, icon: "crown" });
  }
  if (valid(lastHit))
    cards.push({ label: "LATEST HIT", score: lastHit, icon: "flame" });
  const clock = Math.max(0, now);
  const intoSlot = clock % SLOT_MS;
  if (!cards.length || intoSlot >= CARD_MS)
    return null;
  const card = cards[Math.floor(clock / SLOT_MS) % cards.length];
  return {
    label: `${card.label} \xB7 ${card.score.toLocaleString("en-US")}`,
    // Four digits is the physical matrix limit. Larger totals keep their exact
    // value in the caption and show a mark, never a misleading truncated number.
    glyph: intoSlot < INTRO_MS || card.score > 9999 ? `#${card.icon}` : String(card.score),
    score: card.score
  };
}

