  const env = punchArcQuakeEnvelope(elapsedMs, spec.ms);
  if (env <= 0)
    return { x: 0, y: 0, z: 0, pitchDeg: 0, rollDeg: 0 };
  const t2 = Math.max(0, elapsedMs) / 1e3;
  const throwM = spec.throwM * env;
  const drop2 = (spec.dropM ?? 0) * punchArcDrop01(Math.max(0, elapsedMs) / spec.ms);
  const heave = Math.sin(t2 * 69) * 0.62 + Math.sin(t2 * 112) * 0.26 + Math.sin(t2 * 173) * 0.12;
  const sway = Math.sin(t2 * 54) * 0.72 + Math.sin(t2 * 131) * 0.28;
  const surge = Math.sin(t2 * 61) * 0.6;
