// src/plugins/index.ts
function shortPluginName(id2) {
  return id2.replace(/^swissverse\./, "");
}
var STARTERS = {
  [GATE_APP.id]: startGatePlugin,
  [LANDING_APP.id]: startLandingPlugin,
  [WORLD_MAP_APP.id]: startWorldMapPlugin,
  [OBJECT_STUDIO_APP.id]: startObjectStudioPlugin,
  [PUNCH_MACHINE_APP.id]: startPunchMachinePlugin
};
function startScenePlugins(ctx) {
  initAdminFx();
  const plan = planPluginStart({
    manifests: FIRST_PARTY_PLUGIN_MANIFESTS,
    enabledPluginIds: enabledPluginIdsFromApps(ctx.social.apps),
    availableBindings: bindingsFromBehaviors(ctx.handles.map((handle) => handle.spec.behavior)),
    grantedOverrides: []
  });
  for (const result of plan.results) {
    const extra = result.reason ? ` \u2014 ${result.reason}` : "";
    console.log(`[plugin] ${result.pluginId} ${result.status}${extra}`);
    if (result.status === "blocked") {
      reportBootHealth(shortPluginName(result.pluginId), "failed", result.reason);
    }
  }
  for (const slot2 of plan.schedule)
    markPluginActive(slot2.pluginId);
  for (const slot2 of plan.schedule) {
    const starter = STARTERS[slot2.pluginId];
    if (!starter) {
      console.log(`[plugin] ${slot2.pluginId} started \u2014 missing scene starter`);
      continue;
    }
    const run2 = () => starter(ctx);
    if (slot2.delayS <= 0) {
      try {
        run2();
        reportBootHealth(shortPluginName(slot2.pluginId), "ok");
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        console.log(`[plugin] ${slot2.pluginId} FAILED \u2014 ${message}`);
        reportBootHealth(shortPluginName(slot2.pluginId), "failed", message);
      }
      continue;
    }
    afterBoot(slot2.delayS, shortPluginName(slot2.pluginId), run2);
    console.log(`[plugin] ${slot2.pluginId} ${slot2.loadClass} +${slot2.delayS}s`);
  }
  return plan.results;
}

