    kind: spec.kind,
    mesh: "box",
    x: (a.x + b3.x) / 2,
    y: spec.y,
    z: (a.z + b3.z) / 2,
    rotX: 0,
    rotY: Math.atan2(dx, dz),
    rotZ: 0,
    sx: spec.width,
    sy: spec.height,
    sz: len,
    color: spec.color,
    roughness: spec.roughness,
